// === Tab: mySketch ===
// Scribbly Doods v1.0.0 - WCCChallenge: Child's Art
// By Im A. Void 2025
// instagram.com/ima.void
// Attribution-NonCommercial-ShareAlike 3.0
// ===== Instructions:
// ===== Press SPACE to regenerate
// ===== Press 's' to save a PNG
// ===== Mouse around for eye tracking.

let seed;
let splash;
let eyes;
let baseLayer; // 存储背景图层的图像缓存？这个baseLayer是什么类型的变量？
//答：baseLayer是 p5.js 图像缓存对象（PImage 类型）
//用于存储已经绘制好的静态背景（比如颜料飞溅效果）。


function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 255);
	noLoop();
	seed = Math.floor(random(1e9)); // 生成随机种子（9位数）“Math.floor()”是干什么用的？执行逻辑是什么?
	//random(1e9)：生成一个 0 到 10亿（1e9）之间的随机浮点数（比如 123456789.87）。
	//Math.floor()：JavaScript 内置函数，向下取整（去掉小数部分，只保留整数）。
	//执行逻辑：先随机生成一个小数，再用 Math.floor切成整数，最终得到 9位数的随机整数种子（比如 123456789）。
	generate();
	document.title = "Scribbly Doods v1.0.0 - WCCChallenge: Child's Art by Im A. Void";
}

function draw() {
	if (baseLayer) {//baseLayer是布尔变量？
		//不是。这里是判断 baseLayer是否“存在”（是否为“真值”）。
		//JavaScript 中，变量如果未赋值、为 null或 undefined，会被当作“假值”（false）；如果有值（比如图像对象），则为“真值”（true）。
		//这里 if (baseLayer)等价于“如果 baseLayer已经生成（有图像缓存），就执行下面的代码”。
		background(255);
		image(baseLayer, 0, 0);
		//直接用 image(baseLayer, 0, 0)把这个缓存图像贴回画布，避免重复绘制复杂背景，提升效率。
	} else {
		background(255);
	}

	if (eyes) {
		eyes.update();
		eyes.draw();
	}
}

function keyPressed() {
	if (key === ' ' || key === 'Spacebar') { // 空格键：重新生成场景
		seed = Math.floor(random(1e9)); // 新随机种子
		generate();
	}
	if (key === 's' || key === 'S') { // S键：保存画布为PNG图片
		saveCanvas("scribbly-doods_by-ImAVoid_" + nf(int(random(100000)), 5), "png");
	}
}

function windowResized() { // 响应窗口大小变化
	resizeCanvas(windowWidth, windowHeight);
	seed = Math.floor(random(1e9));
	generate();
}

function generate() { //定义画面生成函数
	noLoop(); // 暂停绘制循环
	randomSeed(seed);// 设置随机数种子（确保可复现）randomSeed（）是啥？
	noiseSeed(seed);// 设置噪声种子（Perlin噪声）noiseSeed(）是啥？
	//都是 p5.js 控制随机性的函数，让随机结果《可复现（相同种子生成相同图案）》
	//randomSeed(seed)：设置“普通随机数生成器”的种子。后续调用 random()会按固定顺序生成随机数（比如 random(60,110)每次结果相同）。
	//noiseSeed(seed)：设置“Perlin 噪声生成器”的种子。后续调用 noise()（生成平滑随机值）会按固定顺序输出。
   //举例子:
	//randomSeed(123); // 设种子为123 
	//random(1,10) → 总是 3.14（假设） 
	//noiseSeed(123);  
	//noise(0.5) → 总是 0.72（假设）


	const pal = new Palette().randomSoft();// 创建随机柔和调色板？const是啥
	//const:JavaScript 的常量声明关键字，表示“声明一个只读的变量，一旦赋值就不能修改”。
   //"const pal = new Palette().randomSoft()"：pal的值（调色板对象）不能再被重新赋值（比如后面不能写 pal = 123）

	const center = createVector(width * 0.5, height * 0.5);//画布中心点?createVector又是啥
	//createVector(x, y)：p5.js 的函数，创建一个二维向量对象（可以理解为“带 x/y 坐标的小盒子”），方便处理位置、方向等。
	//例子中 createVector(width*0.5, height*0.5)：生成一个向量，x 是画布宽度的一半，y 是画布高度的一半——即画布中心点的坐标。
   //向量对象的用法：
	//const center = createVector(400, 300); // 中心坐标 (400,300) 
	//center.x → 400（x坐标） 
	//center.y → 300（y坐标）

	const poolR = random(60, 110);//随机半径？const是啥
	splash = new Splash(center, poolR, pal); // 创建颜料飞溅效果实例

	background(255);
	splash.paint();// 绘制颜料飞溅效果

	eyes = new GooglyEyes(center.copy().add(random(-10, 10), random(-10, 10)), poolR * 0.65);// 创建眼睛（位置在中心点附近随机偏移）
   //"center.copy().add(random(-10, 10), random(-10, 10))"是什么写法，执行逻辑是什么？
	//这是向量操作的链式写法，分3步：
	//1.center.copy()：复制 center向量（避免修改原向量，因为向量是引用类型）。
	//2.add(dx, dy)：给复制后的向量加上偏移量（dx是 x 方向偏移，dy是 y 方向偏移）。
	//3.整体效果：在中心点附近随机偏移一个小位置（x 偏移 -10~10 像素，y 偏移 -10~10 像素）。
	//举例子：
	//center = (500, 400)（画布中心）
	//copy() → 新向量 (500,400) 
	//add(random(-10,10), random(-10,10)) → 比如加 (3, -5)，结果 (503, 395)

	baseLayer = get();//get（）是派什么用的？的执行逻辑是什么?
	//代码中通过 baseLayer = get()获取：p5.js 的 get()函数会“拍照”当前画布内容，返回一个图像对象(PImage)存到 baseLayer。

	loop();
}

/* ======================= 颜料飞溅系统  ======================= */

class Splash {//创建一个飞溅的类
	constructor(c, poolR, pal) {//构造函数（初始化）

		this.c = c.copy();//中心点坐标为什么一定要加一个“this.”？这是什么语法？
      //this是 JavaScript 类的关键字，指代“当前实例对象”（每个实例自己的“小标签”）。
		//this.c = c.copy()：把传入的参数 c（中心点向量）复制一份，存到当前实例的属性 c​ 中。
		//为什么加 this？如果不加 this，c只是构造函数的局部变量，实例无法“记住”这个值；加了 this，每个实例就有自己的 c属性，后续可以访问（比如 paint()方法中用 this.c获取中心点）
      //例子：
		//class Splash {
      //constructor(c) {
      //this.c = c.copy(); // 存到实例属性，每个Splash实例都有自己的c
      //}
      //printCenter() {
      //console.log(this.c.x, this.c.y); // 访问实例自己的中心点
      //}
      //}
      //const splash1 = new Splash(createVector(100,100));  
      //splash1.printCenter() → 100,100（用自己的this.c）
		this.poolR = poolR;//颜料池基础半径
		this.pal = pal;//使用的调色板

		this.armCount = Math.floor(random(26, 44));//飞溅臂数量
		this.minLen = random(140, 210);//最小臂长
		this.maxLen = random(280, 440);//最大臂长
		this.branchProb = 0.4;//分支概率
		this.wobble = random(1, 50);//摆动幅度
		this.viscosity = random(0.01, 0.1);//黏度系数（影响线条粗细）
	}

	paint() {
		push();//此处的push相当于processing中的pushmartix吗？
		noStroke();

		 // 绘制多层颜料池（模拟液体扩散效果） 
		const puddleLayers = 28;//层数
		for (let i = puddleLayers; i >= 1; i--) {
			const rr = this.poolR * map(i, 1, puddleLayers, 0.55, 1.35) * (1 + 0.1 * noise(i * 0.13));
			 // 计算当前层半径（随层数变化）
			const col = this.pal.mix(map(i, 1, puddleLayers, 0, 1));
			const alpha = 8 + 120 * pow(map(i, 1, puddleLayers, 1, 0), 3);
			fill(applyAlpha(col, alpha));
			ellipse(
				this.c.x + randomGaussian() * 6,
				this.c.y + randomGaussian() * 6,
				rr * 2,
				rr * 2
			);
		}

		for (let a = 0; a < this.armCount; a++) {
			const baseAng = TWO_PI * a / this.armCount + random(-0.08, 0.08);
			const len = random(this.minLen, this.maxLen);
			const steps = Math.max(1, Math.floor(len / 4));
			const sw0 = map(this.viscosity, 0, 1, 9, 16) * random(0.8, 1.25);
			const taperPow = map(this.viscosity, 0, 1, 0.9, 2.3);

			const c0 = this.pal.mix(random(0, 0.6));
			const c1 = this.pal.mix(random(0.4, 1));

			const start = p5.Vector.fromAngle(baseAng)
				.mult(this.poolR * 0.9 + random(4, 10))
				.add(this.c);

			let p = start.copy();
			let dir = p5.Vector.fromAngle(baseAng);
			const nOff = random(1000);

			for (let s = 0; s < steps; s++) {
				const t = s / steps;
				const ang = baseAng + this.wobble * (noise(nOff + s * 0.03) - 0.5);
				dir = p5.Vector.fromAngle(ang);
				const stepLen = 10 + 3 * pow(1 - t, 2);
				const q = p5.Vector.add(p, p5.Vector.mult(dir, stepLen));

				const cc = lerpColor(c0, c1, easeOutCubic(t));

				const sw = Math.max(1, sw0 * pow(1 - t, taperPow)) * random(1.5, 2);

				const alphaSeg = 8 + 120 * pow(1.5 - t, 6);

				stroke(applyAlpha(cc, alphaSeg));
				strokeCap(ROUND);
				strokeWeight(sw);

				const jig = pow(0.3 - t, 5);
				const px = p.x + randomGaussian() * jig;
				const py = p.y + randomGaussian() * jig;
				const qx = q.x + randomGaussian() * jig;
				const qy = q.y + randomGaussian() * jig;

				line(px, py, qx, qy);

				const dropletDensity = map(this.viscosity, 0, 1, 0.8, 0.25);
				if (random(1) < dropletDensity) {
					const k = Math.floor(random(1, 3));
					for (let j = 0; j < k; j++) {
						var rr = random(0.8, 2.2) * (1 + 0.2 * (1 - t));
						const off = random(2, 11) * (1 + 0.6 * (1 - t));
						const side = random(-1, 1);
						const ang2 = ang + side * random(0.25, 1.25);
						const dx = cos(ang2) * off;
						const dy = sin(ang2) * off;
						noStroke();
						fill(
							applyAlpha(
								lerpColor(c0, c1, constrain(t + random(-0.15, 0.15), 0, 1)),
								random(140, 240)
							)
						);
						ellipse(q.x + dx, q.y + dy, rr * 2, rr * 2);
					}
				}

				if (random(1) < this.branchProb * (1 - t)) {
					const bAng = ang + random(-1.2, 1.2);
					const bLen = stepLen * random(12, 24);
					this.drawBranch(q.copy(), bAng, bLen, sw * 0.5, c0, c1);
				}
				p = q;
			}
		}
		pop();
	}

	drawBranch(start, ang, len, sw, c0, c1) {
		var steps = Math.max(1, Math.floor(len / 3));
		var nOff = random(1000);
		var p = start.copy();
		for (let s = 0; s < steps; s++) {
			var t = s / steps;
			const a = ang + 0.5 * (noise(nOff + s * 0.07) - 0.5);
			var dir = p5.Vector.fromAngle(a);
			var stepLen = 3;
			var q = p5.Vector.add(p, p5.Vector.mult(dir, stepLen));
			const swt = Math.max(0.8, sw * pow(1 - t, 1.6)) * random(0.9, 1.15);
			var cc = lerpColor(c0, c1, t);

			var alphaSeg = 8 + 120 * pow(1 - t, 3);

			stroke(applyAlpha(cc, alphaSeg));
			strokeWeight(swt);

			var jig = pow(1 - t, 0.05);
			var px = p.x + randomGaussian() * jig;
			var py = p.y + randomGaussian() * jig;
			var qx = q.x + randomGaussian() * jig;
			var qy = q.y + randomGaussian() * jig;

			line(px, py, qx, qy);

			if (random(1) < 0.15) {
				noStroke();
				fill(applyAlpha(cc, 210));
				ellipse(q.x, q.y, swt, swt);
			}
			p = q;
		}
	}
}

/* ======================= 眼睛系统 ======================= */

class GooglyEyes {
	constructor(anchor, baseR) {
		this.anchor = anchor.copy();
		this.eyeR = constrain(baseR, 20, 25);
		const gap = this.eyeR * random(1.5, 1.6);
		const base = this.anchor.copy().add(0, -this.eyeR * 0.25);
		const leftCenter = base.copy().add(-gap * 0.6, 0);
		const rightCenter = base.copy().add(gap * 0.6, 0);
		this.left = new Eye(leftCenter, this.eyeR);
		this.right = new Eye(rightCenter, this.eyeR);
	}

	update() {
		this.left.update();
		this.right.update();
	}

	draw() {
		this.left.draw();
		this.right.draw();

		noFill();
		stroke(0, 0, 40, 150);
		strokeWeight(5);
		const wSmile = this.eyeR * 2.5;
		arc(this.anchor.x, this.anchor.y + this.eyeR * 0.95, wSmile, wSmile * 0.7, 0.15, PI - 0.15);
	}
}

class Eye {
	constructor(c, r) {
		this.c = c.copy();
		this.r = r;
		this.pupilR = r * 0.4;
		this.nOffX = random(1000);
		this.nOffY = random(2000);
		this.pupilCx = this.c.x;
		this.pupilCy = this.c.y;
	}

	update() {
		const range = this.r * 0.4;
		let tx = map(noise(this.nOffX + frameCount * 0.01), 0, 1, -range, range);
		let ty = map(noise(this.nOffY + frameCount * 0.014), 0, 1, -range, range);

		if (dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), this.c.x, this.c.y) < this.r * 10) {
			const toM = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - this.c.x, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - this.c.y);
			toM.limit(range * 2);
			tx += random(-5, 5);
			ty += random(-5, 5);
			tx = lerp(tx, toM.x, 0.5);
			ty = lerp(ty, toM.y, 0.5);
		}

		this.pupilCx = lerp(this.pupilCx, this.c.x + tx, 0.15);
		this.pupilCy = lerp(this.pupilCy, this.c.y + ty, 0.15);
	}

	draw() {
		noStroke();
		fill(255);
		ellipse(this.c.x, this.c.y, this.r * 2, this.r * 2);

		push();
		noFill();
		stroke(0, 0, 0, 40);
		strokeWeight(6);
		ellipse(this.c.x, this.c.y, this.r * 2.02, this.r * 2.02);
		pop();

		var px = this.pupilCx;
		var py = this.pupilCy;
		fill(25);
		ellipse(px, py, this.pupilR * 2, this.pupilR * 2);

		fill(255, 230);
		ellipse(px - this.pupilR * 0.35, py - this.pupilR * 0.35, this.pupilR * 0.6, this.pupilR * 0.6);
	}
}

/* ======================= 颜色工具 ======================= */

class Palette {
	constructor() {
		this.h1 = 0;
		this.h2 = 0;
		this.h3 = 0;
		this.s = 0;
		this.b = 0;
	}

	randomSoft() {
		var base = random(0, 360);
		this.h1 = base;
		this.h2 = base + random(110, 160);
		this.h3 = base + random(200, 260);
		this.s = random(0.55, 0.85);
		this.b = random(0.8, 0.98);
		return this;
	}

	mix(t) {
		const seg = random(1) < 0.5 ? 0 : 1;
		const hA = seg === 0 ? this.h1 : this.h2;
		const hB = seg === 0 ? this.h2 : this.h3;
		colorMode(HSB, 360, 1, 1, 1);
		const c = lerpColor(
			color(this.normHue(hA), this.s, this.b, 1),
			color(this.normHue(hB), this.s, this.b, 1),
			constrain(t, 0, 1)
		);
		colorMode(HSB, 255);
		return c;
	}

	normHue(h) {
		let nh = h % 360;
		if (nh < 0) nh += 360;
		return nh;
	}
}

function easeOutCubic(t) {
	const tt = constrain(t, 0, 1);
	return 1 - pow(1 - tt, 3);
}

function applyAlpha(col, alpha) {
	var c = color(col);
	c.setAlpha(alpha);
	return c;
}






//const和let的区别：
//关键字	能否重新赋值？	能否先声明后赋值？	本质特点
//const	❌ 不能（声明后值固定）	❌ 不能（必须声明时直接赋值）	常量（只读变量）
//let 	✅ 能（值可以随时改）	✅ 能（可以先声明，后赋值）	变量（可变的量）
//2. 作用域：都是「块级作用域」（比 var 安全）
//const 和 let 都遵循 “块级作用域”：变量只在 {} 内有效（比如 if、for、函数 的大括号里），出了块就“消失”。
//这和老旧的 var（函数级作用域，容易污染全局）不同，更安全。

